// document represents the current HTML document.

// window -> browser window / global context
console.log(window.innerWidth);

// document -> current HTML document
console.log(document.title);

// navigator -> browser/environment information
console.log(navigator.language);
console.log(navigator.onLine);

// Frontend running on:
// https://myapp.com

// API running on:
// https://api.example.com

fetch("https://api.example.com/users")
  .then(response => response.json())
  .then(data => console.log(data));

// The API server must provide appropriate CORS headers
// if the browser is going to allow the frontend to read
// the cross-origin response.

// Example:
// A malicious website should not automatically be able
// to read sensitive data from another website in the user's browser.

// CORS allows the target server to explicitly say:
// "Requests from this origin are allowed."

// Example response header:
// Access-Control-Allow-Origin: https://myapp.com

// Same origin
https://example.com/page1
https://example.com/page2

// Different origin - different host
https://example.com
https://api.example.com

// Different origin - different scheme
http://example.com
https://example.com

// Different origin - different port
https://example.com:3000
https://example.com:4000

// localStorage
localStorage.setItem("theme", "dark");
console.log(localStorage.getItem("theme"));

// sessionStorage
sessionStorage.setItem("step", "2");
console.log(sessionStorage.getItem("step"));

// Cookie
document.cookie = "theme=dark; Max-Age=3600; Path=/";
console.log(document.cookie);

// Important differences:
// localStorage   -> persists until removed
// sessionStorage -> usually lasts for the page session/tab
// cookies        -> can be sent automatically with HTTP requests

// Setting a cookie from JavaScript
document.cookie = "theme=dark; Max-Age=3600; Path=/";

// Reading cookies accessible to JavaScript
console.log(document.cookie);

